Add SharePoint List Item.code:
// Add a row to a SharePoint list.
create(
  // 1) Resource path, relative to https://graph.microsoft.com/{apiVersion}/
  `sites/${$.configuration.siteId}/lists/${$.data.listId}/items`,
  // 2) The list item; column values go under `fields`.
  {
    fields: {
      Title: $.data.beneficiaryName,
      HouseholdId: $.data.householdId,
      District: $.data.district,
      EnrolmentDate: $.data.enrolledOn,
    },
  }
);

Send Email.code:
// Send an email on behalf of a user (or shared mailbox).
create(
  // 1) The sendMail action for the sending mailbox.
  `users/${$.configuration.senderId}/sendMail`,
  // 2) The message to send.
  {
    message: {
      subject: `Stock-out alert: ${$.data.facilityName}`,
      body: {
        contentType: 'Text',
        content: `${$.data.itemName} is out of stock at ${$.data.facilityName}.`,
      },
      toRecipients: [
        { emailAddress: { address: 'supply-chain@example.org' } },
      ],
    },
    // Keep a copy in the sender's Sent Items.
    saveToSentItems: true,
  }
);

Post Message to Teams Channel.code:
// Post a message into a Teams channel.
create(
  // 1) The channel's messages collection.
  `teams/${$.configuration.teamId}/channels/${$.configuration.channelId}/messages`,
  // 2) The chatMessage body.
  {
    body: {
      contentType: 'html',
      content: `<b>New referral</b> for case ${$.data.caseId} in ${$.data.district}.`,
    },
  }
);

Create Calendar Event.code:
// Create an event on a user's calendar.
create(
  // 1) The user's calendar events collection.
  `users/${$.data.userId}/calendar/events`,
  // 2) The event details.
  {
    subject: 'Community health worker refresher training',
    start: { dateTime: '2026-11-20T09:00:00', timeZone: 'Africa/Nairobi' },
    end: { dateTime: '2026-11-20T12:00:00', timeZone: 'Africa/Nairobi' },
    location: { displayName: 'District Health Office' },
    attendees: [
      {
        emailAddress: { address: 'chw.lead@example.org', name: 'CHW Lead' },
        type: 'required',
      },
    ],
  }
);

Upload File to SharePoint.code:
// Upload a file into a folder in a drive.
uploadFile(
  // 1) Where the file goes and what it's called.
  {
    driveId: $.configuration.driveId,
    folderId: $.configuration.reportsFolderId,
    fileName: `monthly-indicators-${new Date().toISOString().slice(0, 7)}.xlsx`,
    contentType:
      'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',
    // rename | fail | replace
    onConflict: 'replace',
  },
  // 2) A buffer with the file contents, built in an earlier step.
  state => state.buffer
);

List SharePoint List Items.code:
// Get the rows of a SharePoint list, with column values.
get(
  // 1) Path, relative to https://graph.microsoft.com/{apiVersion}/
  `sites/${$.configuration.siteId}/lists/${$.configuration.listId}/items`,
  // 2) OData query parameters.
  {
    $expand: 'fields',
    $top: 100,
  }
);

Download File From SharePoint.code:
// Load the site's default document library into state.drives.default.
getDrive({ id: $.configuration.siteId, owner: 'sites' });

// Then read a file from it by path (or pass a driveItem id).
getFile('/Shared Documents/Registrations/registrations.csv', {
  // Which drive in state.drives to use.
  driveName: 'default',
  // false returns the file content, true returns its metadata.
  metadata: false,
});

List Files in Folder.code:
// Load a drive by id into state.drives.default.
getDrive({ id: $.configuration.driveId });

// List the children of a folder (by driveItem id or path).
getFolder($.configuration.inboxFolderId, {
  driveName: 'default',
});

List Users.code:
// List directory users.
get('users', {
  // Only return the fields you need.
  $select: 'id,displayName,mail,jobTitle,officeLocation',
  $top: 50,
});

List Recent Emails.code:
// Get recent messages from a mailbox.
get(`users/${$.configuration.mailboxId}/messages`, {
  $select: 'id,subject,from,receivedDateTime,hasAttachments',
  $orderby: 'receivedDateTime desc',
  $top: 25,
});
